std::list<Particle*> particles;
for (Particle* p : particles) p->update();

// After: particles stored in place, contiguous
class ParticleSystem {
public:
  void update() {
    for (int i = 0; i < numParticles_; i++)
      particles_[i].update();
  }
private:
  static const int MAX_PARTICLES = 20000;
  int numParticles_ = 0;
  Particle particles_[MAX_PARTICLES];
};

class AIComponent {        // hot: touched every frame
public:
  void update();
private:
  Animation* animation_;
  double     energy_;
  Vector     goalPos_;
  AICold*    cold_;        // rarely used data lives elsewhere
};

class AICold {             // cold: used once, at death
  friend class AIComponent;
  LootType drop_;
  int      minDrops_, maxDrops_;
  double   chanceOfDrop_;
  DialogId deathLine_;
};

// Option B: homogeneous arrays, static dispatch
struct Army {
  std::vector<Archer>   archers;
  std::vector<Knight>   knights;
  std::vector<Catapult> catapults;

  void update() {
    for (Archer& a : archers)     a.update();  // non-virtual
    for (Knight& k : knights)     k.update();
    for (Catapult& c : catapults) c.update();
  }
};

void BulletSystem::activate(int index) {
  assert(index >= numActive_);
  std::swap(bullets_[numActive_], bullets_[index]);
  numActive_++;
}

void BulletSystem::deactivate(int index) {
  assert(index < numActive_);
  numActive_--;
  std::swap(bullets_[numActive_], bullets_[index]);
}

void BulletSystem::update() {
  for (int i = 0; i < numActive_; i++)
    bullets_[i].update();   // no branch, no skipping
}

class PhysicsManager {
public:
  PhysicsComponent& get(EntityId id) {
    return components_[indexOf_[id]];
  }
  void swapSlots(int a, int b) {
    std::swap(components_[a], components_[b]);
    indexOf_[components_[a].owner] = a;   // keep lookup valid
    indexOf_[components_[b].owner] = b;
  }
private:
  std::vector<PhysicsComponent> components_;
  std::vector<int> indexOf_;   // EntityId -> slot
};
